// Chapter 13 Project: Class Report Card Generator
// Uses only: variables, cin/cout, if-else, switch, loops and strings.
#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    const int SUBJECTS = 5;
    const int MAX_MARKS = 100;
    const int PASS_MARKS = 33;

    int students;
    cout << "===== REPORT CARD GENERATOR =====\n";
    cout << "Number of students: ";
    cin >> students;

    // Class summary values
    double classTotal = 0;
    int passCount = 0;
    double topPercent = -1;
    string topper;
    for (int s = 1; s <= students; s++) {
        string name;
        cout << "\nStudent " << s << " name: ";
        cin >> ws;              // skip leftover newline
        getline(cin, name);

        int total = 0;
        bool failedAny = false;

        for (int sub = 1; sub <= SUBJECTS; sub++) {
            int marks;
            // keep asking until the marks are valid
            do {
                cout << "  Marks in subject " << sub << " (0-100): ";
                cin >> marks;
                if (marks < 0 || marks > MAX_MARKS)
                    cout << "  Invalid! Enter again.\n";
            } while (marks < 0 || marks > MAX_MARKS);

            total += marks;
            if (marks < PASS_MARKS)
                failedAny = true;
        }

        double percent = total * 100.0 / (SUBJECTS * MAX_MARKS);

        string grade;
        if (percent >= 90)      grade = "A1";
        else if (percent >= 75) grade = "A2";
        else if (percent >= 60) grade = "B";
        else if (percent >= 45) grade = "C";
        else if (percent >= 33) grade = "D";
        else                    grade = "E";

        string result = failedAny ? "FAIL" : "PASS";

        // Print the report card
        cout << fixed << setprecision(2);
        cout << "\n  ---------------------------------\n";
        cout << "  Name       : " << name << "\n";
        cout << "  Total      : " << total << " / " << SUBJECTS * MAX_MARKS
<< "\n";
        cout << "  Percentage : " << percent << " %\n";
        cout << "  Grade      : " << grade << "\n";
        cout << "  Result     : " << result << "\n";
        cout << "  ---------------------------------\n";
        // Update class summary
        classTotal += percent;
        if (!failedAny)
            passCount++;
        if (percent > topPercent) {
            topPercent = percent;
            topper = name;
        }
    }

    if (students > 0) {
        cout << "\n===== CLASS SUMMARY =====\n";
        cout << "Students        : " << students << "\n";
        cout << "Passed          : " << passCount << "\n";
        cout << "Pass percentage : " << passCount * 100.0 / students << " %\n";
        cout << "Class average   : " << classTotal / students << " %\n";
        cout << "Topper          : " << topper << " (" << topPercent << " %)\n";
    }
    return 0;
}
